# Registers blog-x-following-reply-task: replies to recent posts from accounts @100labjtvn
# follows, and to replies that come back on our own replies. The reply text is generated by
# scripts/x_llm.py (gemini-3.5-flash-lite -> longcat-2.5-free -> claude haiku fallback chain).
#
# 2026-11-16 (user request): a fixed 45-minute trigger looked too mechanical, so the task now
# starts ONE long-lived process (run-following-reply.ps1 -> x-following-reply.py --loop) and
# the script itself sleeps a random interval between cycles: 25-55 min in the daytime
# (07:00-22:59) and 80-150 min late at night (23:00-06:59), about 30 cycles a day with only
# ~4 of them at night. A daily 06:10 trigger plus the logon trigger restart the process if it
# was killed (reboot, crash); MultipleInstances=IgnoreNew prevents a second copy.
#
# Kept ASCII-only: Windows PowerShell 5.1 reads BOM-less UTF-8 .ps1 files as ANSI and breaks on
# Japanese string literals (same reason as schedule-unfollow.ps1).
#
# Usage: powershell -NoProfile -ExecutionPolicy Bypass -File scripts/schedule-following-reply.ps1
#        Stop-ScheduledTask    -TaskName blog-x-following-reply-task   # stop the loop now
#        Disable-ScheduledTask -TaskName blog-x-following-reply-task   # stop it for good

$taskName = "blog-x-following-reply-task"
$repo = "C:\Users\norio\my-github-blog"
$runner = Join-Path $repo "scripts\scheduled\run-following-reply.ps1"
$log = Join-Path $repo "scripts\scheduled\logs\x-following-reply.log"
New-Item -ItemType Directory -Force -Path (Split-Path $log) | Out-Null

# Daily trigger is only a safety net; the real cadence is decided inside the Python loop.
$triggerDaily = New-ScheduledTaskTrigger -Daily -At "06:10"
$triggerLogon = New-ScheduledTaskTrigger -AtLogOn -User "$env:USERDOMAIN\$env:USERNAME"

$action = New-ScheduledTaskAction -Execute "powershell.exe" `
    -Argument "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$runner`"" `
    -WorkingDirectory $repo

# ExecutionTimeLimit PT0S == unlimited: the loop is meant to stay alive all day.
$settings = New-ScheduledTaskSettingsSet -StartWhenAvailable -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries `
    -RunOnlyIfNetworkAvailable -MultipleInstances IgnoreNew -ExecutionTimeLimit ([TimeSpan]::Zero)
$principal = New-ScheduledTaskPrincipal -UserId "$env:USERDOMAIN\$env:USERNAME" -LogonType Interactive -RunLevel Limited

Register-ScheduledTask -TaskName $taskName -Trigger $triggerDaily, $triggerLogon -Action $action -Settings $settings `
    -Principal $principal `
    -Description "X: loop replying to followed accounts' posts and follow-ups (random 25-55min day / 80-150min night, max 1/cycle, 30/day)" `
    -Force | Out-Null

Write-Host "registered $taskName (daily 06:10 + at logon, loop decided in python, log: $log)"
Get-ScheduledTask -TaskName $taskName | Get-ScheduledTaskInfo | Select-Object TaskName, NextRunTime, LastTaskResult
